'use strict';
// Presentation adapters keep itinerary, navigation and time calculations intact.
function visualWeek(d){return new Intl.DateTimeFormat('zh-CN',{weekday:'short',timeZone:'UTC'}).format(new Date(d.date+'T12:00:00Z')).replace('星期','周');}
// Homepage uses the existing schedule model, with compact editorial summaries.
function homeStepIcon(row){const title=row.stepTitle||'';return /报到|集合/.test(title)?'people':/蓝冰洞|峡谷|山峰/.test(title)?'mountain':/拍照|蓝调|瀑布|海滩/.test(title)?'camera':journeyStepKind(row);}
function homeSummaryRows(d,isCurrent){const rows=selectedPlan(d),pos=journeyPosition(d),start=isCurrent&&pos.live?Math.max(0,pos.primary):0;if(isCurrent&&pos.live&&pos.primary<0)return [];
 const score=r=>/^前往|^开往/.test(r.stepTitle||'')?1:/航班|飞|蓝冰洞|浮潜|快艇|追鲸|观鲸|报到|瀑布|间歇泉|渔村|午餐|白沙滩|红屋|缆车/.test(r.stepTitle||'')?5:/早餐|整理|路线选择|退房/.test(r.stepTitle||'')?0:2;
 const next=rows.slice(start).map((r,i)=>({r,i:i+start}));let picks=isCurrent&&pos.live?next.slice(0,3):next.sort((a,b)=>score(b.r)-score(a.r)||a.i-b.i).slice(0,3);return picks.sort((a,b)=>a.i-b.i);}
homeDaySummary=function(d,label,isCurrent=false){const picks=homeSummaryRows(d,isCurrent),key=representative(d)||({1:'cathedral',2:'tromso',5:'ballstad',8:'a',9:'oslo-s',10:'hallgrim',16:'nyhavn',17:'cathedral'})[d.id],src=key&&smallPhoto(key),booking=DATA.bookings.find(b=>b.day===d.id),route=d.flights?.length?d.flights.map(f=>f[1]+' → '+f[4]).join(' · '):d.region;
 return `<article class="home-day-summary ${isCurrent||label==='出发日'||label==='最后一天'?'summary-today':'summary-tomorrow'}" data-summary-key="${d.id}:${picks.map(x=>x.i).join('-')}"><header><p class="summary-badge">${esc(label)}</p><div class="home-summary-heading"><h2>${shortDate(d.date)} · ${esc(d.title)}</h2><p class="home-summary-route">${ico('pin')}${esc(route)}${booking?' · '+booking.people+'人':''}</p></div><button class="home-detail" data-day="${d.id}" aria-label="查看${shortDate(d.date)}完整日程">详情 ›</button></header><div class="home-summary-body ${src?'':'no-photo'}">${src?`<img class="home-summary-photo" src="${src}" width="240" height="320" alt="${esc(DATA.places[key].name)}" loading="eager" decoding="async">`:''}<ol>${picks.map(({r,i})=>{const time=r.time.match(/\d{1,2}:\d{2}/)?.[0]||r.time.replace(/左右|以后/g,'');return `<li><span class="home-time-node" aria-hidden="true"></span><time aria-label="${esc(r.time)}">${esc(time)}</time><span class="home-step-icon">${ico(homeStepIcon(r))}</span><button data-day="${d.id}" data-focus-step="${i}">${esc(journeyTitle(d,r))}</button></li>`;}).join('')||`<li class="summary-ended"><p>当天安排已结束</p>${d.id<18?`<button data-day="${d.id+1}">看看明天 →</button>`:''}</li>`}</ol></div></article>`;};
home=function(){const t=tripToday(new Date(),DATA.days,tripCalendarChanges);return `<section class="home-cover"><img src="${pImage('hamnoy')}" width="1176" height="805" alt="Hamnøy红屋与罗弗敦山海" fetchpriority="high" decoding="async"><div class="home-cover-copy"><h1>Nordic Journal 2026</h1><p class="home-chinese-title">北欧路书</p><p class="home-subtitle">挪威 · 冰岛 · 18天</p><button class="home-all-dates" data-view="itinerary">全部日期 ›</button></div><button class="home-search" data-home-search aria-label="搜索日期、地点或活动"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/></svg></button></section><div class="home-date-entry visual-date-entry"><div class="home-date-strip" role="group" aria-label="选择行程日期">${DATA.days.map(d=>`<button data-home-date="${d.id}" aria-pressed="${d.id===t.day}"><time>${shortDate(d.date)}</time><small>${visualWeek(d)}</small></button>`).join('')}</div><div hidden>${journeyDate(t.day)}</div><button data-open-home-day aria-label="查看所选日期行程">查看日程 →</button></div><section class="journey-home-status"><div class="home-summaries">${homeSummaries(t)}</div></section>${routeOverview()}<footer class="journal-footer"><span>Nordic Journal 2026</span><div><button data-credits>照片来源</button><button data-offline>离线资料</button><button data-top>回到顶部 ↑</button></div></footer>`;};
function mountVisual(){const active=document.querySelector('.home-date-strip [aria-pressed=true]'),strip=active?.parentElement;if(active&&strip)strip.scrollLeft=Math.max(0,active.offsetLeft-strip.offsetLeft-(strip.clientWidth-active.clientWidth)/2);}
function journalSearchText(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9\u3400-\u9fff]/g,'');}
function journalSearchDate(q){q=q.normalize('NFKC').replace(/\s+/g,'').replace(/^2026(?=\d{4}$)/,'');const m=q.match(/^(?:(2026)[年/.-])?(\d{1,2})[月/.-](\d{1,2})(?:日|号)?$/)||q.trim().match(/^(10|11)(\d{2})$/);return m?(m.length===4?`${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`:`${m[1]}-${m[2]}`):null;}
function journalSearchResults(q){q=q.trim();if(!q)return [];q=q.normalize('NFKC');const date=journalSearchDate(q),text=journalSearchText(q);if(date)return DATA.days.filter(d=>d.date.endsWith(date)).map(d=>({day:d.id,title:d.title,subtitle:shortDate(d.date)+' '+visualWeek(d)+' · '+d.region,score:100}));
 const fuzzy=(hay,needle)=>{if(hay.includes(needle))return 4;if(needle.length<2)return 0;let i=0;for(const c of hay)if(c===needle[i])i++;return i===needle.length?1:0;},found=[];
 for(const d of DATA.days){const rows=selectedPlan(d),dayMatch=fuzzy(journalSearchText(d.title+' '+d.region),text);if(dayMatch)found.push({day:d.id,title:d.title,subtitle:shortDate(d.date)+' '+visualWeek(d),score:dayMatch+2});rows.forEach((r,step)=>{const places=(r.nav||[]).map(k=>k.startsWith('hotel:')?DATA.hotels[k.slice(6)]:DATA.places[k]).filter(Boolean),names=places.map(p=>p.name+' '+(p.en||'')+' '+(p.cn||'')).join(' '),booking=DATA.bookings.find(b=>b.day===d.id&&bookingRow(d,b,rows)===step),hay=journalSearchText([r.stepTitle,r.text,names,booking?.name,(r.nav||[]).includes('sakrisoy')?'安妮塔 安尼塔 Anita Anitas':'',booking?.spot==='cave'?'蓝冰洞 Blue Iceland ice cave':'' ].join(' ')),score=fuzzy(hay,text);if(score)found.push({day:d.id,step,title:r.stepTitle,subtitle:shortDate(d.date)+' · '+(places[0]?.name||d.title),score:score+(journalSearchText(r.stepTitle).includes(text)?3:0)});});}
 return found.sort((a,b)=>b.score-a.score||a.day-b.day||(a.step??-1)-(b.step??-1)).slice(0,40);}
function renderJournalSearch(q){const results=journalSearchResults(q),box=$('#journalSearchResults'),status=$('#journalSearchStatus');if(!box)return;status.textContent=q.trim()?(results.length?'找到 '+results.length+' 项':'没有找到，试试日期、地点中文名或英文名'):'例如：1030、10月30日、蓝冰洞、Hamnoy';box.innerHTML=results.map(r=>`<button class="journal-search-result" data-day="${r.day}" ${r.step!==undefined?`data-focus-step="${r.step}"`:''}><strong>${esc(r.title)}</strong><span>${esc(r.subtitle)}</span>${outlineIco('arrow')}</button>`).join('');}
function openJournalSearch(){openDrawer('搜索路书',`<form id="journalSearchForm" role="search"><label for="journalSearchInput">日期、地点或活动</label><div class="journal-search-field"><input id="journalSearchInput" type="search" placeholder="10/30、蓝冰洞、Hali…" autocomplete="off" enterkeyhint="search"><button type="submit">搜索</button></div></form><p id="journalSearchStatus" role="status"></p><div id="journalSearchResults"></div>`);renderJournalSearch('');requestAnimationFrame(()=>$('#journalSearchInput')?.focus());}
document.addEventListener('input',e=>{if(e.target.id==='journalSearchInput'&&!e.isComposing)renderJournalSearch(e.target.value);});
document.addEventListener('compositionend',e=>{if(e.target.id==='journalSearchInput')renderJournalSearch(e.target.value);});
document.addEventListener('submit',e=>{if(e.target.id!=='journalSearchForm')return;e.preventDefault();const results=journalSearchResults($('#journalSearchInput').value);if(results.length===1){const r=results[0];navigate('day',r.day,{restore:false,focusStep:r.step});}else $('#journalSearchResults button')?.focus();});
document.addEventListener('click',e=>{if(e.target.closest('[data-home-search]'))openJournalSearch();});
const visualOriginalDayView=dayView;
dayView=function(){const tpl=document.createElement('template');tpl.innerHTML=visualOriginalDayView();const header=tpl.content.querySelector('.day-utility'),nav=tpl.content.querySelector('.day-top-controls');if(header&&nav)tpl.content.insertBefore(nav,header);return [...tpl.content.childNodes].map(n=>n.outerHTML||n.textContent).join('');};
const visualOriginalToolbox=toolboxView;
toolboxView=function(){const tpl=document.createElement('template');tpl.innerHTML=visualOriginalToolbox();const header=tpl.content.querySelector('.utility-header'),sub=document.createElement('p');sub.className='toolbox-subtitle';sub.textContent='旅途中随时取用的信息';header.append(sub);const icons={activities:'pin',flights:'plane',hotels:'bed',transport:'car',emergency:'phone',lists:'bag',offline:'bag',roads:'map'};tpl.content.querySelectorAll('[data-tool]').forEach(b=>{b.insertAdjacentHTML('afterbegin',outlineIco(icons[b.dataset.tool]||'pin'));});return [...tpl.content.childNodes].map(n=>n.outerHTML||n.textContent).join('');};
const visualOriginalBookingQuick=bookingQuick;
bookingQuick=function(b){const tpl=document.createElement('template');tpl.innerHTML=visualOriginalBookingQuick(b);const card=tpl.content.firstElementChild,src=smallPhoto(b.spot);if(src){card.insertAdjacentHTML('afterbegin',`<img class="tool-card-photo" src="${src}" width="160" height="120" alt="${esc(DATA.places[b.spot]?.name||b.name)}" loading="lazy" decoding="async">`);}return card.outerHTML;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-home-date]');if(b){const select=document.querySelector('.home-date-entry [data-journey-date]');if(select)select.value=b.dataset.homeDate;document.querySelectorAll('[data-home-date]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}});
function visualBookingDetail(b){const d=DATA.days[b.day-1],p=DATA.places[b.meeting||b.spot],src=pImage(b.spot),place=DATA.places[b.spot];return `<div class="visual-booking-detail">${src?`<div class="detail-photo"><img src="${src}" width="1200" height="800" alt="${esc(place?.name||b.name)}" loading="eager" fetchpriority="high" decoding="async"></div>`:''}<p class="detail-en">${dateText(d.date)} · ${esc(d.region)}</p><div class="booking-badges"><span>已订</span><span>${b.people}人参加</span></div><dl class="visual-booking-facts"><div><dt>报到目标</dt><dd>${esc(b.report)}</dd></div><div><dt>活动时间</dt><dd>${esc(b.time)}</dd></div><div><dt>集合位置</dt><dd>${esc(b.place)}</dd></div><div><dt>参与人数</dt><dd>${b.people}人</dd></div></dl><div class="booking-primary-actions">${ext(navLink(p),'导航到集合点','primary-link')}<button data-day="${b.day}" data-focus-step="${bookingRow(d,b)}">当日安排</button></div>${place?.desc?`<details class="journey-disclosure"><summary>活动简介</summary><div class="journey-detail-body"><p>${inline(place.desc)}</p></div></details>`:''}<details class="journey-disclosure"><summary>集合与凭证说明</summary><div class="journey-detail-body">${bookingNavigation(b)}</div></details><details class="journey-disclosure"><summary>注意事项</summary><div class="journey-detail-body"><p>${inline(b.note)}</p></div></details></div>`;}

// Broken photographs do not leave large empty panels or dead image controls.
document.addEventListener('error',e=>{const img=e.target;if(!(img instanceof HTMLImageElement))return;if(img.matches('.map-row-thumb,.tool-card-photo'))img.remove();else if(img.closest('.detail-photo'))img.closest('.detail-photo').remove();else if(img.matches('.home-summary-photo')){img.closest('.home-summary-body')?.classList.add('no-photo');img.remove();}},true);
